#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/cuda/vector_select.h>

void bind_vector_select(py::module& m)
{
    using vector_select = gr::cuda::vector_select;

    // A single integer index is accepted as a one-element list.
    py::class_<vector_select,
               gr::sync_block,
               gr::block,
               gr::basic_block,
               std::shared_ptr<vector_select>>(m, "vector_select")
        .def(py::init(&vector_select::make),
             py::arg("itemsize"),
             py::arg("vlen"),
             py::arg("indices"),
             py::arg("output_multiple") = 1)
        .def(py::init([](size_t itemsize, size_t vlen, int index, int output_multiple) {
                 return vector_select::make(itemsize, vlen, { index }, output_multiple);
             }),
             py::arg("itemsize"),
             py::arg("vlen"),
             py::arg("indices"),
             py::arg("output_multiple") = 1)
        .def("set_indices", &vector_select::set_indices, py::arg("indices"))
        .def(
            "set_indices",
            [](vector_select& self, int index) { self.set_indices({ index }); },
            py::arg("indices"));
}
